    /**
     * assign Finding on CorrectiveAction
     * @param		command AssignFindingToCorrectiveActionCommand	
     * @exception	ProcessingException
     */     
	public void assignFinding( AssignFindingToCorrectiveActionCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getCorrectiveActionId() );
		
		AuditFindingService childDelegate 	= AuditFindingService.getAuditFindingInstance();
		CorrectiveActionService parentDelegate = CorrectiveActionService.getCorrectiveActionInstance();			
		UUID childId = command.getAssignment().getAuditFindingId();
		AuditFinding child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get AuditFinding using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

